<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\JobFair;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class JobFairController{public function index():JsonResponse{return response()->json(['data'=>JobFair::where('status','published')->where('ends_at','>=',now())->orderBy('starts_at')->get()]);}public function show(JobFair $fair):JsonResponse{abort_unless($fair->status==='published',404);return response()->json(['data'=>['fair'=>$fair,'companies'=>DB::table('job_fair_companies')->join('companies','companies.id','=','job_fair_companies.company_id')->where('job_fair_id',$fair->id)->where('job_fair_companies.status','approved')->get(['companies.name','companies.slug','job_fair_companies.booth_title','job_fair_companies.booth_description'])]]);}public function register(Request $r,JobFair $fair):JsonResponse{abort_unless($r->user()->account_type==='candidate'&&$fair->status==='published'&&$fair->ends_at->isFuture(),422);DB::table('job_fair_registrations')->updateOrInsert(['job_fair_id'=>$fair->id,'user_id'=>$r->user()->id],['created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Registro confirmado.']);}public function join(Request $r,JobFair $fair):JsonResponse{$c=$this->company($r);abort_unless($c->verification_status==='verified'&&$fair->status==='published',422);$d=$r->validate(['booth_title'=>['nullable','string','max:150'],'booth_description'=>['nullable','string','max:2000']]);DB::table('job_fair_companies')->updateOrInsert(['job_fair_id'=>$fair->id,'company_id'=>$c->id],[...$d,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Participación enviada para aprobación.']);}public function adminIndex(Request $r):JsonResponse{$this->admin($r);return response()->json(['data'=>JobFair::latest()->get()]);}public function store(Request $r):JsonResponse{$this->admin($r);$d=$r->validate(['title'=>['required','string','max:180'],'description'=>['required','string','max:5000'],'format'=>['required',Rule::in(['online','in_person','hybrid'])],'location_or_link'=>['nullable','string','max:500'],'starts_at'=>['required','date','after:now'],'ends_at'=>['required','date','after:starts_at'],'status'=>['required',Rule::in(['draft','published'])]]);$f=JobFair::create([...$d,'created_by'=>$r->user()->id,'slug'=>Str::slug($d['title']).'-'.Str::lower(Str::random(6))]);return response()->json(['data'=>$f],201);}public function reviewCompany(Request $r,JobFair $fair,int $company):JsonResponse{$this->admin($r);$d=$r->validate(['status'=>['required',Rule::in(['approved','rejected'])]]);abort_unless(DB::table('job_fair_companies')->where(['job_fair_id'=>$fair->id,'company_id'=>$company])->update([...$d,'updated_at'=>now()]),404);return response()->json(['message'=>'Participación revisada.']);}private function company(Request $r){abort_unless($r->user()->account_type==='company',403);return$r->user()->companies()->wherePivot('status','active')->firstOrFail();}private function admin(Request $r):void{abort_unless($r->user()->is_admin,403);}}
